 <button class="tab on" data-view="home"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="m3 11 9-8 9 8v9H3z"/><path d="M9 20v-6h6v6"/></svg>Главная</button>
 <button class="tab" data-view="music"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M9 18V5l11-2v13"/><circle cx="6" cy="18" r="3"/><circle cx="17" cy="16" r="3"/></svg>Музыка</button>
 <button class="tab" data-view="tools"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M12 3v18M3 12h18"/><circle cx="12" cy="12" r="8"/></svg>Инструменты</button>
 <button class="tab" data-view="weather"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M7 17h10a4 4 0 0 0 0-8 6 6 0 0 0-11-1A4.5 4.5 0 0 0 7 17Z"/></svg>Погода</button>
 <button class="tab" data-view="site"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/></svg>Сайт</button>
</div></nav>
<script>
(()=>{'use strict';
const $=id=>document.getElementById(id), tg=window.Telegram?.WebApp, initData=tg?.initData||'', demo=new URLSearchParams(location.search).get('demo')==='1';
const state={boot:null,site:null,owner:false,pwa:!initData,connection:null};
if(tg){tg.ready();tg.expand();try{tg.setHeaderColor('#000000');tg.setBackgroundColor('#000000')}catch(e){}}
const esc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('toast').classList.remove('show'),2600)}
function haptic(kind='light'){try{tg?.HapticFeedback?.impactOccurred(kind)}catch(e){}}
function ask(text,yes){if(tg?.showConfirm)tg.showConfirm(text,yes);else yes(confirm(text))}
function demoBoot(){return{ok:true,app_version:'0.7.0',user:{id:42,first_name:'Владелец',is_owner:true},metrics:{cpu_percent:18,ram_used_percent:43,disk_used_percent:61},status:{now_listening:'M83 — Midnight City',now_source:'pc_agent',now_source_label:'PC',weather:'Москва: 24.1°C, малооблачно, ощущается как 25.2°C, ветер 2.7 м/с',discord_tag:'owner',vk_connected:false},settings:{save_mode:'SAVE_FULL',quiet_enabled:true,away_enabled:false,away_message:'Привет, я сейчас не в сети. Сообщение сохранено — отвечу, как смогу.'},sources:[{source_name:'Домашний ПК',source_type:'PC_AGENT',is_online:true,last_seen_at:new Date().toISOString(),agent_version:'0.7.0',last_payload:{platform:'Windows'}}],services:{nginx:'active',postgresql:'active'},windows_installer:{available:true,version:'0.7.0',size:73400320,file_name:'XASS-Setup.exe'},vk_app_id:''}}
function demoApi(path,opts={}){let data={ok:true};if(path==='bootstrap')data=demoBoot();else if(path.startsWith('music'))data={ok:true,artist:'M83',title:'Midnight City',album:'Hurry Up, We’re Dreaming',artwork_url:'',links:{VK:'#',Shazam:'#','Apple Music':'#',Google:'#','Yandex Music':'#'}};else if(path==='site')data={ok:true,can_edit:true,public_url:'/profile.php',profile:{name:'XASS',username:'lucifervalter',title:'Системы, которые остаются живыми.',bio:'Собираю сервисы и интерфейсы.',telegram_url:'https://t.me/lucifervalter',avatar_url:'',quote:'Делаю сложное спокойным.',stack:['Python','FastAPI'],links:[{label:'GitHub',url:'https://github.com/lucifervalter-a11y'}]},projects:[{id:'xass',title:'XASS',status:'live',description:'Личный центр управления.',years:{from:2025,to:2026},tags:['Python'],cover:{src:''}}]};else if(path.startsWith('logs'))data={ok:true,logs:[{chat_title:'XASS',direction:'system',text:'Heartbeat получен',date:new Date().toISOString()}]};else if(path==='quotes')data={ok:true,quotes:[{id:'1',text:'Делаем просто и надёжно.'}]};else if(path==='agents/pair-code')data={ok:true,code:'XASS2048',ttl_minutes:15,server_url:location.origin,connection:{format:'xass-connect',version:1,server_url:location.origin,pair_code:'XASS2048',auto_update:true}};else if(path==='update-status')data={ok:true,has_updates:true,commits:[{subject:'UI and PWA'}]};else if(path==='run-update'||path==='restart')data={ok:true,restart_scheduled:false,steps:['Готово']};else if(path.includes('/commands'))data={ok:true,command:{status:'pending'}};else if(path==='setting')data={ok:true,settings:state.boot.settings,status:state.boot.status};else if(path==='vk-url')data={ok:true,url:'#'};return Promise.resolve({status:200,data})}
function api(path,opts={}){if(demo)return demoApi(path,opts);const headers=new Headers(opts.headers||{});if(initData)headers.set('X-Telegram-Init-Data',initData);if(opts.body&&typeof opts.body!=='string'){headers.set('Content-Type','application/json');opts.body=JSON.stringify(opts.body)}return fetch('/proxy.php?_p='+encodeURIComponent('/api/mini/'+path),{...opts,headers,credentials:'include'}).then(async r=>{const env=await r.json();let data=null;try{data=JSON.parse(env._b||'')}catch(e){}return{status:Number(env._s||r.status),data,raw:env._b||''}})}
async function pwaApi(path,opts={}){const headers=new Headers(opts.headers||{});if(opts.body&&typeof opts.body!=='string'){headers.set('Content-Type','application/json');opts.body=JSON.stringify(opts.body)}const response=await fetch('/proxy.php?_passthrough=1&_p='+encodeURIComponent('/api/pwa/'+path),{...opts,headers,credentials:'include'});let data=null;try{data=await response.json()}catch(e){}return{status:Number(response.headers.get('X-XASS-Status')||response.status),data}}
function metricHtml(m={}){return[['CPU',m.cpu_percent],['Память',m.ram_used_percent],['Диск',m.disk_used_percent]].map(([name,v])=>{v=Math.max(0,Math.min(100,Number(v)||0));return'<div class="metric"><div class="metric-name">'+name+'</div><div class="metric-value">'+Math.round(v)+'%</div><div class="metric-bar"><i style="width:'+v+'%"></i></div></div>'}).join('')}
function age(iso){if(!iso)return'нет данных';const sec=Math.max(0,(Date.now()-new Date(iso).getTime())/1000);return sec<60?Math.round(sec)+' сек назад':sec<3600?Math.floor(sec/60)+' мин назад':Math.floor(sec/3600)+' ч назад'}
function versionAtLeast(value,wanted){const a=String(value||'0').split('.').map(Number),b=wanted.split('.').map(Number);for(let i=0;i<3;i++){if((a[i]||0)>(b[i]||0))return true;if((a[i]||0)<(b[i]||0))return false}return true}
function isPc(item){return /pc|windows/i.test(String(item.source_type||'')+' '+String(item.last_payload?.platform||''))}
function deviceHtml(list,actions=false){return(list||[]).map(item=>{const pc=isPc(item),old=pc&&!versionAtLeast(item.agent_version,'0.6.0');return'<div class="row"><svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7">'+(pc?'<rect x="3" y="4" width="18" height="13" rx="2"/><path d="M8 21h8m-4-4v4"/>':'<rect x="4" y="3" width="16" height="7" rx="2"/><rect x="4" y="14" width="16" height="7" rx="2"/>')+'</svg><div class="row-main"><div class="row-title">'+esc(item.source_name)+'</div><div class="row-sub">v'+esc(item.agent_version||'0.0.0')+' · '+age(item.last_seen_at)+'</div>'+(old?'<div class="warning">Для блокировки установите свежий агент.</div>':'')+(actions&&state.owner?'<div class="device-actions"><button class="btn blue agent-command" data-source="'+esc(item.source_name)+'" data-command="update">Обновить</button><button class="btn agent-command" data-source="'+esc(item.source_name)+'" data-command="restart">Перезапустить</button>'+(pc?'<button class="btn danger agent-command" data-source="'+esc(item.source_name)+'" data-command="lock">Заблокировать экран</button>':'')+'</div>':'')+'</div><span class="status '+(item.is_online?'':'off')+'">'+(item.is_online?'В сети':'Offline')+'</span></div>'}).join('')||'<div class="empty">Устройства ещё не подключены.</div>'}
function renderSettings(s={}){const modes={SAVE_OFF:'Выключено',SAVE_BASIC:'Базовый',SAVE_FULL:'Полный + медиа',SAVE_PRIVATE_ONLY:'Только личные',SAVE_GROUPS_ONLY:'Только группы'};$('saveModeDesc').textContent=modes[s.save_mode]||s.save_mode||'—';$('quietToggle').classList.toggle('on',!!s.quiet_enabled);$('quietDesc').textContent=s.quiet_enabled?'Включены':'Выключены';$('awayToggle').classList.toggle('on',!!s.away_enabled);$('awayDesc').textContent=s.away_enabled?'Автоответ включён':'Выключен';$('awayMessage').value=s.away_message||'';updateAwayCount()}
function renderMusic(status={}){const source=status.now_source||'pc_agent',raw=String(status.now_listening||'').trim(),stale=!raw||/нет (свежих )?данных|ничего не играет/i.test(raw);document.querySelectorAll('#sourceSeg button').forEach(b=>b.classList.toggle('on',b.dataset.source===source));$('homeSource').textContent=status.now_source_label||source;$('musicSourceLabel').textContent='Источник · '+(status.now_source_label||source);$('homeTrack').textContent=stale?'Нет свежих данных':raw;$('musicNow').textContent=stale?'Нет свежих данных':raw;$('homeTrackHint').textContent=stale?'Выберите ПК, iPhone или VK — поиск музыки всё равно доступен.':'Нажмите раздел «Музыка», чтобы открыть трек в сервисах.';$('musicEmptyHint').textContent=stale?'Источник пока не прислал трек. Введите название ниже или переключите источник.':'Можно найти этот трек во всех сервисах ниже.';$('musicInput').value=stale?'':raw;$('discordTag').value=status.discord_tag||'';$('vkState').textContent=status.vk_connected?'подключён':'не подключён'}
function renderWeather(text=''){const parts=String(text||'').split(',').map(x=>x.trim()).filter(Boolean),first=parts.shift()||'Погода обновляется…';let place='Погода',main=first;if(first.includes(':')){const cut=first.indexOf(':');place='Погода · '+first.slice(0,cut);main=first.slice(cut+1).trim()}$('weatherPlace').textContent=place;$('weatherMain').textContent=main;$('weatherDetails').textContent=parts.join(' · ')||'Свежая сводка появится после обновления сервера.'}
function renderInstaller(info={}){$('downloadInstallerBtn').disabled=!info.available;$('installerMeta').textContent=info.available?'Версия '+(info.version||'—')+' · '+(info.size?Math.max(1,Math.round(info.size/1048576))+' МБ':'готов к загрузке'):'Установщик ещё собирается'}
function bindCommands(){document.querySelectorAll('.agent-command').forEach(btn=>btn.onclick=()=>{const run=()=>{btn.disabled=true;api('agents/'+encodeURIComponent(btn.dataset.source)+'/commands',{method:'POST',body:{command:btn.dataset.command,payload:{}}}).then(r=>{btn.disabled=false;toast(r.data?.ok?(btn.dataset.command==='lock'?'Команда Win + L отправлена':'Команда отправлена'):(r.data?.detail||'Ошибка'))}).catch(()=>{btn.disabled=false;toast('Нет связи')})};btn.dataset.command==='lock'?ask('Заблокировать экран '+btn.dataset.source+'? Разблокировка возможна только паролем, PIN или Windows Hello на самом ПК.',ok=>ok&&run()):run()})}
function renderBoot(data){state.boot=data;state.owner=!!data.user?.is_owner;$('appVersion').textContent='XASS '+(data.app_version||'');$('headStatus').textContent='В сети';$('headDot').className='dot ok';$('helloTitle').textContent=(data.user?.first_name?'Привет, '+data.user.first_name+'.':'Система в сети.');$('homeMetrics').innerHTML=metricHtml(data.metrics);$('serverMetrics').innerHTML=metricHtml(data.metrics);$('homeDevices').innerHTML=deviceHtml((data.sources||[]).slice(0,3));$('deviceList').innerHTML=deviceHtml(data.sources||[],true);bindCommands();renderSettings(data.settings);renderMusic(data.status);renderWeather(data.status?.weather);renderInstaller(data.windows_installer||{});$('vkAppId').value=data.vk_app_id||'';$('serviceList').innerHTML=Object.entries(data.services||{}).map(([name,value])=>'<div class="row"><div class="row-main"><div class="row-title">'+esc(name)+'</div></div><span class="status '+(value==='active'?'':'off')+'">'+esc(value)+'</span></div>').join('')||'<div class="empty">Сервисы не настроены.</div>';$('gate').style.display='none';$('app').hidden=false;$('tabs').hidden=false;$('logoutBtn').style.display=state.pwa?'inline-block':'none'}
function loadBoot(){return api('bootstrap').then(r=>{if(r.status!==200||!r.data?.ok)throw new Error(r.data?.detail||'Нет доступа');renderBoot(r.data)}).catch(error=>showDeny(error.message))}
function showDeny(text){$('loader').style.display='none';$('login').style.display='none';$('deny').style.display='block';$('denyText').textContent=text||'Не удалось подключиться.'}
function showView(name){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('on',v.id==='view-'+name));document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('on',t.dataset.view===name));scrollTo({top:0,behavior:'smooth'});if(name==='site'&&!state.site)loadSite();if(name==='tools')loadUpdateStatus()}
document.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>showView(button.dataset.view));$('retryBtn').onclick=()=>location.reload();$('refreshBtn').onclick=loadBoot;
function pushSetting(key,value,done){api('setting',{method:'POST',body:{key,value}}).then(r=>{if(!r.data?.ok)return toast(r.data?.detail||'Ошибка');if(r.data.settings){state.boot.settings=r.data.settings;renderSettings(r.data.settings)}if(r.data.status){state.boot.status=r.data.status;renderMusic(r.data.status)}done?.()})}
$('saveModeBtn').onclick=()=>pushSetting('save_mode_cycle',null);$('quietToggle').onclick=()=>pushSetting('quiet_toggle',null);$('awayToggle').onclick=()=>pushSetting('away_toggle',null);$('awaySaveBtn').onclick=()=>pushSetting('away_message',$('awayMessage').value,()=>toast('Автоответ сохранён'));function updateAwayCount(){$('awayCount').textContent=$('awayMessage').value.length+' / 4000'}$('awayMessage').addEventListener('input',updateAwayCount);
document.querySelectorAll('#sourceSeg button').forEach(button=>button.onclick=()=>pushSetting('now_source',button.dataset.source,()=>{renderMusic({...state.boot.status,now_source:button.dataset.source,now_source_label:button.textContent});toast('Источник изменён')}));
async function findMusic(){const q=$('musicInput').value.trim();if(!q)return toast('Введите исполнителя и трек');$('musicBtn').disabled=true;$('musicBtn').textContent='Ищу…';try{const r=await api('music?q='+encodeURIComponent(q));if(!r.data?.ok)throw new Error(r.data?.detail||'Не найдено');const d=r.data;$('musicResult').style.display='block';$('musicTitle').textContent=[d.artist,d.title].filter(Boolean).join(' — ')||d.query;$('musicMeta').textContent=d.album||'Альбом не указан';$('musicArt').src=d.artwork_url||'/assets/xass-app-icon-192.png';$('musicLinks').innerHTML=Object.entries(d.links||{}).map(([label,url])=>'<a href="'+esc(url)+'" target="_blank" rel="noopener">'+esc(label)+' ↗</a>').join('');haptic('medium')}catch(e){toast(e.message)}finally{$('musicBtn').disabled=false;$('musicBtn').textContent='Найти'}}$('musicBtn').onclick=findMusic;$('musicInput').addEventListener('keydown',e=>{if(e.key==='Enter')findMusic()});
$('discordSave').onclick=()=>pushSetting('discord_tag',$('discordTag').value,()=>toast('Discord сохранён'));$('vkSave').onclick=()=>pushSetting('vk_app_id',$('vkAppId').value,()=>toast('VK App ID сохранён'));$('vkConnect').onclick=()=>api('vk-url?chat_id='+(state.boot?.user?.id||'')).then(r=>{if(!r.data?.ok)return toast(r.data?.detail||'Сначала сохраните VK App ID');const url=r.data.url;if(tg?.openLink)tg.openLink(url);else window.open(url,'_blank')});
$('pairBtn').onclick=function(){this.disabled=true;api('agents/pair-code',{method:'POST',body:{server_url:location.origin}}).then(r=>{this.disabled=false;if(!r.data?.ok)return toast(r.data?.detail||'Ошибка');state.connection=r.data.connection;$('pairPanel').style.display='block';$('pairCode').textContent=r.data.code;$('pairServerUrl').value=r.data.server_url||location.origin;$('pairExpiry').textContent='Ключ действует '+r.data.ttl_minutes+' мин'})};function connection(){return state.connection?{...state.connection,server_url:$('pairServerUrl').value.trim(),pair_code:$('pairCode').textContent.trim()}:null}$('downloadPairBtn').onclick=()=>{const p=connection();if(!p)return;const url=URL.createObjectURL(new Blob([JSON.stringify(p,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='xass-connect.xass';a.click();setTimeout(()=>URL.revokeObjectURL(url),700)};$('copyPairBtn').onclick=()=>{const p=connection();if(!p)return;navigator.clipboard?.writeText('Сервер: '+p.server_url+'\nКлюч: '+p.pair_code);toast('Скопировано')};
$('downloadInstallerBtn').onclick=async function(){if(demo)return toast('Демо: XASS-Setup.exe');this.disabled=true;try{const headers={};if(initData)headers['X-Telegram-Init-Data']=initData;const response=await fetch('/proxy.php?_binary=1&_p='+encodeURIComponent('/api/mini/agent-installer/download'),{headers,credentials:'include'}),status=Number(response.headers.get('X-XASS-Status')||response.status);if(status!==200)throw new Error('HTTP '+status);const url=URL.createObjectURL(await response.blob()),a=document.createElement('a');a.href=url;a.download=state.boot?.windows_installer?.file_name||'XASS-Setup.exe';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('Установщик скачан')}catch(e){toast('Не удалось скачать установщик')}finally{renderInstaller(state.boot.windows_installer||{})}};
function loadUpdateStatus(){api('update-status').then(r=>{const d=r.data||{};$('updateResult').style.display='block';$('updateResult').textContent=d.has_updates?'Доступно изменений: '+(d.commits||[]).length:'Сервер обновлён';$('runUpdateBtn').disabled=!d.has_updates})}$('checkUpdateBtn').onclick=loadUpdateStatus;$('runUpdateBtn').onclick=function(){this.disabled=true;$('updateResult').style.display='block';$('updateResult').textContent='Устанавливаю обновление…';api('run-update',{method:'POST'}).then(r=>{$('updateResult').textContent=r.data?.ok?'Готово\n'+(r.data.steps||[]).join('\n'):'Ошибка: '+(r.data?.error||r.data?.detail||'нет данных');this.disabled=false}).catch(()=>{$('updateResult').textContent='Связь прервана — сервер перезапускается.';this.disabled=false})};$('restartServerBtn').onclick=()=>ask('Перезапустить backend XASS?',ok=>{if(ok)api('restart',{method:'POST'}).then(()=>toast('Перезапуск запланирован'))});
function loadLogs(){api('logs?limit=30').then(r=>{$('logList').innerHTML=(r.data?.logs||[]).map(x=>'<div class="log"><div class="log-meta"><span>'+esc(x.chat_title||x.from_username||'XASS')+' · '+esc(x.direction||'')+'</span><span>'+(x.date?new Date(x.date).toLocaleString('ru-RU'):'')+'</span></div><div class="log-text">'+esc(x.text||'')+'</div></div>').join('')||'<div class="empty">Сообщений нет.</div>'})}$('logsBtn').onclick=loadLogs;function loadQuotes(){api('quotes').then(r=>{$('quoteList').innerHTML=(r.data?.quotes||[]).map(x=>'<div class="quote"><span>'+esc(x.text)+'</span><button class="btn danger quote-delete" data-id="'+esc(x.id)+'">Удалить</button></div>').join('')||'<div class="empty">Цитат нет.</div>';document.querySelectorAll('.quote-delete').forEach(b=>b.onclick=()=>api('quotes/'+encodeURIComponent(b.dataset.id),{method:'DELETE'}).then(loadQuotes))})}$('quoteAdd').onclick=()=>{const text=$('quoteInput').value.trim();if(!text)return;api('quotes',{method:'POST',body:{text}}).then(r=>{if(r.data?.ok){$('quoteInput').value='';loadQuotes()}})};document.querySelectorAll('.disclosure details')[1].addEventListener('toggle',e=>{if(e.target.open)loadQuotes()});$('copyDiag').onclick=()=>{const b=state.boot||{},safe={app_version:b.app_version,status:b.status,sources:(b.sources||[]).map(x=>({source_name:x.source_name,source_type:x.source_type,is_online:x.is_online,last_seen_at:x.last_seen_at,agent_version:x.agent_version})),metrics:b.metrics,services:b.services};navigator.clipboard?.writeText(JSON.stringify(safe,null,2));toast('Диагностика скопирована')};
function renderSite(data){state.site=data;const p=data.profile||{};for(const [id,key] of [['siteName','name'],['siteUsername','username'],['siteTitle','title'],['siteBio','bio'],['siteTelegram','telegram_url'],['siteAvatar','avatar_url'],['siteQuote','quote']])$(id).value=p[key]||'';$('siteStack').value=(p.stack||[]).join(', ');$('siteLinks').value=(p.links||[]).map(x=>(x.label||'')+' | '+(x.url||'')).join('\n');renderProjects(data.projects||[])}function loadSite(){api('site').then(r=>r.data?.ok?renderSite(r.data):toast(r.data?.detail||'Ошибка сайта'))}function profilePayload(){return{name:$('siteName').value,username:$('siteUsername').value,title:$('siteTitle').value,bio:$('siteBio').value,telegram_url:$('siteTelegram').value,avatar_url:$('siteAvatar').value,quote:$('siteQuote').value,stack:$('siteStack').value.split(',').map(x=>x.trim()).filter(Boolean),links:$('siteLinks').value.split('\n').map(line=>{const parts=line.split('|');return{label:(parts.shift()||'').trim(),url:parts.join('|').trim()}}).filter(x=>x.label&&x.url)}}$('saveProfileBtn').onclick=function(){this.disabled=true;api('site/profile',{method:'POST',body:profilePayload()}).then(r=>{this.disabled=false;r.data?.ok?toast('Профиль сохранён'):toast(r.data?.detail||'Ошибка')})};$('openSiteBtn').onclick=()=>{const url=state.site?.public_url||location.origin+'/profile.php';tg?.openLink?tg.openLink(url):window.open(url,'_blank')};
function renderProjects(list){state.site=state.site||{};state.site.projects=list;$('projectList').innerHTML=list.map(p=>'<div class="project"><div class="project-head"><div><div class="project-name">'+esc(p.title)+'</div><div class="project-desc">'+esc(p.description||p.subtitle||'Без описания')+'</div></div><span class="status">'+esc(p.status||'dev')+'</span></div><div class="device-actions"><button class="btn edit-project" data-id="'+esc(p.id)+'">Изменить</button><button class="btn danger delete-project" data-id="'+esc(p.id)+'">Удалить</button></div></div>').join('')||'<div class="empty">Проектов пока нет.</div>';document.querySelectorAll('.edit-project').forEach(b=>b.onclick=()=>openProject(list.find(p=>p.id===b.dataset.id)||{}));document.querySelectorAll('.delete-project').forEach(b=>b.onclick=()=>ask('Удалить проект?',ok=>ok&&api('site/projects/'+encodeURIComponent(b.dataset.id),{method:'DELETE'}).then(r=>r.data?.ok&&renderProjects(r.data.projects))))}
function openProject(p={}){const y=new Date().getFullYear();$('projectForm').style.display='block';$('projectFormTitle').textContent=p.id?'Редактировать проект':'Новый проект';$('projectId').value=p.id||'';$('projectTitle').value=p.title||'';$('projectStatus').value=p.status||'dev';$('projectSubtitle').value=p.subtitle||'';$('projectDescription').value=p.description||'';$('projectUrl').value=p.url||'';$('projectFrom').value=p.years?.from||y;$('projectTo').value=p.years?.to||y;$('projectTags').value=(p.tags||[]).join(', ');$('projectCover').value=p.cover?.src||'';$('projectFeatured').checked=!!p.featured;$('projectForm').scrollIntoView({behavior:'smooth'})}function projectPayload(){return{id:$('projectId').value,title:$('projectTitle').value,status:$('projectStatus').value,subtitle:$('projectSubtitle').value,description:$('projectDescription').value,url:$('projectUrl').value,year_from:Number($('projectFrom').value),year_to:Number($('projectTo').value),tags:$('projectTags').value.split(',').map(x=>x.trim()).filter(Boolean),cover_type:'image',cover_src:$('projectCover').value,featured:$('projectFeatured').checked}}$('newProjectBtn').onclick=()=>openProject();$('cancelProjectBtn').onclick=()=>{$('projectForm').style.display='none'};$('saveProjectBtn').onclick=function(){if(!$('projectTitle').value.trim())return toast('Введите название');this.disabled=true;api('site/projects',{method:'POST',body:projectPayload()}).then(r=>{this.disabled=false;if(r.data?.ok){renderProjects(r.data.projects);$('projectForm').style.display='none';toast('Проект сохранён')}else toast(r.data?.detail||'Ошибка')})};
$('logoutBtn').onclick=()=>pwaApi('logout',{method:'POST'}).then(()=>location.reload());
async function initPwa(){try{const r=await pwaApi('config');if(r.data?.authenticated)return loadBoot();$('loader').style.display='none';$('login').style.display='block';if(!r.data?.login_ready){$('telegramWidget').innerHTML='<div class="empty">Укажите TELEGRAM_BOT_USERNAME на сервере и привяжите домен через /setdomain в BotFather.</div>';return}window.onTelegramAuth=async user=>{try{const login=await pwaApi('login',{method:'POST',body:user});if(login.status!==200||!login.data?.ok)throw new Error(login.data?.detail||'Вход отклонён');$('login').style.display='none';$('loader').style.display='flex';await loadBoot()}catch(e){toast(e.message)}};const script=document.createElement('script');script.async=true;script.src='https://telegram.org/js/telegram-widget.js?22';script.dataset.telegramLogin=r.data.bot_username;script.dataset.size='large';script.dataset.userpic='false';script.dataset.radius='0';script.dataset.onauth='onTelegramAuth(user)';$('telegramWidget').appendChild(script)}catch(e){showDeny('Backend недоступен: '+e.message)}}
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
demo||initData?loadBoot():initPwa();
})();
</script>
</body></html>
